// === Tab: mySketch ===
var mass = [];
var positionX = [];
var positionY = [];
var velocityX = [];
var velocityY = [];
var colour =[];
var clickState = 0;
var pos = 0;

/////////////////////////////////////////////////////////////////////////////////////////////////////

function setup() {
	createCanvas(windowWidth, windowHeight);
	noStroke();
	fill(64, 255, 155, 133);
  mass.push(0.07);
	positionX.push(800);
	positionY.push(400);
	velocityX.push(0);
	velocityY.push(0);
	colour.push(254);
	clickState = 0;
	//fill(122);
	pos = height / 2;
}


/////////////////////////////////////////////////////////////////////////////////////////////////////



function mouseWheel(event) {
  //print(event.delta);
  //move the square according to the vertical scroll amount
  pos += event.delta;
  //uncomment to block page scrolling
  //return false;
}

function draw() {
	background(32);
	var spread = 0;
	var jay = 0;
	switch (clickState){
		case 0:
			fill( 164,255,111, 133); 
			ellipse(width-90, pos ,50,30);
			 spread = pos;
			break;
		case 1:
			 fill( 64,55,111, 133); 
			 ellipse(width-60, pos ,30,30);
		   jay = pos;
			break;
		case 2:
			fill( 64,125,122, 133); 
			 ellipse(width-120,pos,30,30);
			break;
		case 3:
			fill( 255,255,22, 133); 
			 ellipse(width-160,pos,30,30);
			 clickState = 0;
			break;

			 ;
			break;


	}


	for (var particleA = 0; particleA < mass.length; particleA++) {
		var accelerationX = 0, 
				accelerationY = 0;

		for (var particleB = 0; particleB < mass.length; particleB++) {
			if (particleA != particleB) {
				var distanceX = positionX[particleB] - positionX[particleA];
				var distanceY = positionY[particleB] - positionY[particleA];

				var distance = sqrt(distanceX * distanceX + distanceY * distanceY);
				if (distance < 1) distance = 1;

				var force = (distance - 320 + (spread * 0.2)) * mass[particleB] / distance;
				accelerationX += force * distanceX;
				accelerationY += force * distanceY;
			}
		}

		velocityX[particleA] = velocityX[particleA] * 0.99 + accelerationX * mass[particleA];
		velocityY[particleA] = velocityY[particleA] * 0.99 + accelerationY * mass[particleA];
	}

	for (var particle = 0; particle < mass.length; particle++) {
		positionX[particle] += velocityX[particle] + random() - 0.5; //added Brownian motion
		positionY[particle] += velocityY[particle] + random() - 0.5;
		if  (colour[particle] == 254) {
		  fill(100,42,45);

		}else{

			fill( 64,255 - (jay * 0.2) ,colour[particle], 133); 
		}

		ellipse(positionX[particle], positionY[particle], mass[particle] * 1000, mass[particle] * 1000);
	}

}

/////////////////////////////////////////////////////////////////////////////////////////////////////

function addNewParticle() {
	mass.push(random(0.003, 0.04));
	positionX.push((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))));
	positionY.push((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
	velocityX.push(0);
	velocityY.push(0);
	colour.push(round(random (255)));
	//console.log(mass);
}

/////////////////////////////////////////////////////////////////////////////////////////////////////

function mouseClicked() {
	if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < (width - 100))
	{ 
		addNewParticle();
	}else{
		clickState =+ clickState + 1;
		print(clickState);
	}
}

/////////////////////////////////////////////////////////////////////////////////////////////////////

function mouseDragged() {
	addNewParticle();
}

